// === Tab: Sketch ===
// By Roni Kaufman
// inspired by https://www.instagram.com/p/B7F8Uwln0l3/?igshid=oijtmrzffmq2

let x = 0;
let t = 0;

let colors;
let resolutions;

function setup() {
	createCanvas(600, 600);
	//colorMode(HSB, 100);
	background(255);
	noStroke();

	let alpha = 255;
	colors = [color(255, 0, 0, alpha), 
						color(0, 255, 0, alpha), 
						color(0, 0, 255, alpha)];
	shuffle(colors, true);

	res = 1 / random(300, 1000);
}

function draw() {
	let noice, digit;
	for (let y = 0; y < height; y += 0.5) {
		blendMode(DIFFERENCE);
		for (let j = 0; j < colors.length; j++) {
			fill(colors[j]);
			noice = noise(x * res, y * res, j/50 + t);
			digit = floor(noice * 100);
			if (digit % 2 === 0) {
				square(x, y, 0.5);
			}
		}
		blendMode(BLEND);
		fill(255);
		square(x + 1, y, 1);
	}
	x += 0.5;
	if (x > width) {
		//let newColors = shuffle(colors);
		//while (colors === newColors) newColors = shuffle(colors);
		//colors = newColors;
		shuffle(colors, true);
		t += 1;
		x = -1;
	}
}
